from decimal import Decimal


def _value(source: dict | None, key: str):
    if not source or key not in source:
        return ""
    return source[key]


def _numeric(value) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _date_ge(left, right) -> bool:
    if left is None or right is None:
        return False
    left = str(left)
    right = str(right)
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    amount = _value(record, "AMT")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    # OPP-001
    if event in {"INSERT", "UPDATE"}:
        if not (_numeric(amount) >= Decimal(0)):
            add("E3001", "Amount negative")

    # OPP-002
    if event in {"INSERT", "UPDATE"}:
        if not (stat_cd == "W" and _numeric(amount) == Decimal(0)):
            pass
        else:
            add("E3002", "Won opportunity requires amount")

    # OPP-003
    if event in {"INSERT", "UPDATE"}:
        if not (stat_cd == "L" and lost_rsn == ""):
            pass
        else:
            add("E3003", "Lost reason required")

    # OPP-004
    if event in {"INSERT", "UPDATE"}:
        if not (stat_cd == "W" and close_dt == "00000000"):
            pass
        else:
            add("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if old_stat_cd == "W" and stat_cd != "W":
            add("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    if event in {"INSERT", "UPDATE"}:
        stage = _numeric(stage_pct)
        consistent = (
            (stat_cd == "P" and stage == Decimal(10))
            or (stat_cd == "Q" and stage == Decimal(25))
            or (stat_cd == "N" and stage == Decimal(60))
            or (stat_cd == "W" and stage == Decimal(100))
            or (stat_cd == "L" and stage == Decimal(0))
        )
        if not consistent:
            add("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        if not (
            close_dt == "00000000"
            or _date_ge(close_dt, today)
        ):
            add("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
